122	static int best_class(const float *probabilities)
123	{
124	  int best = 0;
125	  int i;
126	
127	  for (i = 1; i < AUDIO_EVENT_CLASS_COUNT; i++)
128	    {
129	      if (probabilities[i] > probabilities[best])
130	        {
131	          best = i;
132	        }
133	    }
134	
135	  return best;
136	}
137	
138	static void print_probabilities(uint64_t timestamp_ms)
139	{
140	  int best = best_class(g_probabilities);
141	
142	  printf("[infer] t=%llu ms class=%s probs=[%.3f %.3f %.3f %.3f]\n",
143	         (unsigned long long)timestamp_ms, g_event_names[best],
144	         g_probabilities[0], g_probabilities[1], g_probabilities[2],
145	         g_probabilities[3]);
146	}
147	
148	static int run_model_smoke(void)
149	{
150	  int ret;
151	
152	  memset(g_features, 0, sizeof(g_features));
153	  ret = event_classifier_predict(g_features, AUDIO_EVENT_FEATURE_SIZE,
154	                                 g_probabilities,
155	                                 AUDIO_EVENT_CLASS_COUNT);
156	  if (ret < 0)
157	    {
158	      return ret;
159	    }
160	
161	  print_probabilities(0);
162	  return 0;
163	}
164	
165	static void ring_append(size_t *write_position, const int16_t *samples,
166	                        size_t sample_count)
167	{
168	  size_t i;
169	
170	  for (i = 0; i < sample_count; i++)
171	    {
172	      g_audio_ring[*write_position] = samples[i];
173	      *write_position = (*write_position + 1) % AUDIO_EVENT_CLIP_SAMPLES;
174	    }
175	}
176	
177	static void ring_copy_window(size_t write_position)
178	{
179	  size_t tail = AUDIO_EVENT_CLIP_SAMPLES - write_position;
180	
181	  memcpy(g_audio_window, &g_audio_ring[write_position],
182	         tail * sizeof(int16_t));
183	  if (write_position > 0)
184	    {
185	      memcpy(&g_audio_window[tail], g_audio_ring,
186	             write_position * sizeof(int16_t));
187	    }
188	}
189	
190	static int process_window(size_t write_position, uint64_t timestamp_ms)
191	{
192	  struct event_detection_s detection;
193	  int ret;
194	
195	  ring_copy_window(write_position);
196	  ret = feature_extract_compute(g_audio_window, AUDIO_EVENT_CLIP_SAMPLES,
197	                                g_features, AUDIO_EVENT_FEATURE_SIZE);
198	  if (ret < 0)
199	    {
200	      fprintf(stderr, "[feature] compute failed: %d\n", ret);
201	      return ret;
202	    }
203	
204	  ret = event_classifier_predict(g_features, AUDIO_EVENT_FEATURE_SIZE,
205	                                 g_probabilities,
206	                                 AUDIO_EVENT_CLASS_COUNT);
207	  if (ret < 0)
208	    {
209	      fprintf(stderr, "[model] prediction failed: %d\n", ret);
210	      return ret;
211	    }
212	
213	  print_probabilities(timestamp_ms);
214	  ret = event_detector_update(g_probabilities, AUDIO_EVENT_CLASS_COUNT,
215	                              timestamp_ms, &detection);
216	  if (ret < 0)
217	    {
218	      return ret;
219	    }
220	
221	  if (detection.fired)
222	    {
223	      event_alert_fire(detection.class_id,
224	                       g_event_names[detection.class_id],
225	                       detection.confidence);
226	    }
227	
228	  return 0;
229	}
