231	int main(int argc, char *argv[])
232	{
233	  struct app_options_s options;
234	  struct audio_file_s file_source;
235	  size_t write_position = 0;
236	  size_t samples_until_inference = AUDIO_EVENT_CLIP_SAMPLES;
237	  uint64_t total_samples = 0;
238	  unsigned int windows = 0;
239	  bool file_open = false;
240	  bool capture_open = false;
241	  int ret;
242	
243	  memset(&file_source, 0, sizeof(file_source));
244	  file_source.fd = -1;
245	
246	  ret = parse_options(argc, argv, &options);
247	  if (ret != 0)
248	    {
249	      return ret > 0 ? 0 : EXIT_FAILURE;
250	    }
251	
252	  printf("=== Audio Event Detection ===\n");
253	  ret = event_classifier_init();
254	  if (ret < 0)
255	    {
256	      return EXIT_FAILURE;
257	    }
258	
259	  if (options.model_smoke)
260	    {
261	      ret = run_model_smoke();
262	      event_classifier_deinit();
263	      return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
264	    }
265	
266	  ret = feature_extract_init();
267	  if (ret < 0)
268	    {
269	      event_classifier_deinit();
270	      return EXIT_FAILURE;
271	    }
272	
273	  event_detector_init();
274	  ret = event_alert_init();
275	  if (ret < 0)
276	    {
277	      fprintf(stderr, "[alert] init failed: %d, serial output remains\n", ret);
278	    }
279	
280	  if (options.mode == INPUT_MODE_FILE)
281	    {
282	      ret = audio_file_open(&file_source, options.path,
283	                            options.repeat_count);
284	      file_open = ret == 0;
285	    }
286	  else
287	    {
288	      ret = audio_capture_init(options.path);
289	      capture_open = ret == 0;
290	    }
291	
292	  if (ret < 0)
293	    {
294	      goto cleanup;
295	    }
296	
297	  printf("[app] source=%s hop=%d ms\n",
298	         options.mode == INPUT_MODE_FILE ? "file" : "device",
299	         CONFIG_EXAMPLES_AUDIO_EVENT_HOP_MS);
300	
301	  for (;;)
302	    {
303	      size_t request = samples_until_inference;
304	      ssize_t count;
305	
306	      if (request > AUDIO_IO_BLOCK_SAMPLES)
307	        {
308	          request = AUDIO_IO_BLOCK_SAMPLES;
309	        }
310	
311	      if (options.mode == INPUT_MODE_FILE)
312	        {
313	          count = audio_file_read(&file_source, g_audio_block, request);
314	        }
315	      else
316	        {
317	          count = audio_capture_read(g_audio_block, request);
318	        }
319	
320	      if (count < 0)
321	        {
322	          ret = (int)count;
323	          fprintf(stderr, "[app] audio read failed: %d\n", ret);
324	          break;
325	        }
326	
327	      if (count == 0)
328	        {
329	          ret = windows > 0 ? 0 : -ENODATA;
330	          if (ret < 0)
331	            {
332	              fprintf(stderr, "[app] input ended before one full window\n");
333	            }
334	
335	          break;
336	        }
337	
338	      ring_append(&write_position, g_audio_block, count);
339	      total_samples += count;
340	      samples_until_inference -= count;
341	
342	      if (samples_until_inference == 0)
343	        {
344	          uint64_t timestamp_ms = total_samples * 1000 /
345	                                  AUDIO_EVENT_SAMPLE_RATE;
346	          ret = process_window(write_position, timestamp_ms);
347	          if (ret < 0)
348	            {
349	              break;
350	            }
351	
352	          windows++;
353	          if (options.once)
354	            {
355	              ret = 0;
356	              break;
357	            }
358	
359	          samples_until_inference =
360	              AUDIO_EVENT_SAMPLE_RATE *
361	              CONFIG_EXAMPLES_AUDIO_EVENT_HOP_MS / 1000;
362	          if (samples_until_inference == 0 ||
363	              samples_until_inference > AUDIO_EVENT_CLIP_SAMPLES)
364	            {
365	              fprintf(stderr, "[app] invalid hop configuration\n");
366	              ret = -EINVAL;
367	              break;
368	            }
369	        }
370	    }
371	
372	cleanup:
373	  if (file_open)
374	    {
375	      audio_file_close(&file_source);
376	    }
377	
378	  if (capture_open)
379	    {
380	      audio_capture_deinit();
381	    }
382	
383	  event_alert_deinit();
384	  feature_extract_deinit();
385	  event_classifier_deinit();
386	  printf("[app] stopped, windows=%u status=%d\n", windows, ret);
387	  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
388	}
