2	/**
3	 * ReAct 推理循环执行体。
4	 *
5	 * 由 agent_run() 调用，负责实际的迭代推理：
6	 *   1. session add user message
7	 *   2. for iter < max_steps:
8	 *      - check cancel / deadline
9	 *      - build context (context_builder)
10	 *      - build tool schema (tool_schema)
11	 *      - model.complete()
12	 *      - parse response
13	 *      - if final → return
14	 *      - if tool_calls → execute tools → continue
15	 *   3. return AGENT_ERROR_LIMIT
16	 *
17	 * 工具调用在 P1 阶段顺序执行。工具级错误会以 tool result JSON 写回
18	 * session，让模型在下一轮自行处理。
19	 */
20	
21	#include "agent_internal.h"
22	
23	#include "../runtime/runtime.h"
24	#include "../types_internal.h"
25	
26	#include <stddef.h>
27	#include <string.h>
