29	static const char *error_code_to_str(int code)
30	{
31	    switch (code) {
32	    case AGENT_OK:                   return "ok";
33	    case AGENT_ERROR_NOMEM:          return "nomem";
34	    case AGENT_ERROR_INVALID:        return "invalid";
35	    case AGENT_ERROR_BUSY:           return "busy";
36	    case AGENT_ERROR_LIMIT:          return "limit";
37	    case AGENT_ERROR_TIMEOUT:        return "timeout";
38	    case AGENT_ERROR_CANCELLED:      return "cancelled";
39	    case AGENT_ERROR_CONTEXT_OVERFLOW: return "context_overflow";
40	    case AGENT_ERROR_MODEL:          return "model_error";
41	    case AGENT_ERROR_NETWORK:        return "network";
42	    case AGENT_ERROR_TOOL:           return "tool_error";
43	    case AGENT_ERROR_POLICY_DENIED:  return "policy_denied";
44	    case AGENT_ERROR_NOTFOUND:       return "not_found";
45	    case AGENT_ERROR_NOTSUP:         return "not_supported";
46	    case AGENT_ERROR_PARSE:          return "parse_error";
47	    default:                         return "unknown";
48	    }
49	}
