51	static int check_run_state(agent_t *agent)
52	{
53	    uint64_t now;
54	
55	    if (!agent) {
56	        return AGENT_ERROR_INVALID;
57	    }
58	
59	    if (agent->cancel_requested) {
60	        return AGENT_ERROR_CANCELLED;
61	    }
62	
63	    now = agent_runtime_now_ms(&agent->runtime);
64	    if (agent->run_deadline_ms != 0u && now > agent->run_deadline_ms) {
65	        return AGENT_ERROR_TIMEOUT;
66	    }
67	
68	    return AGENT_OK;
69	}
