71	static int copy_final_output(agent_response_t *response, const char *content)
72	{
73	    size_t len;
74	
75	    if (!response || !response->output || response->output_size == 0u) {
76	        return AGENT_ERROR_INVALID;
77	    }
78	
79	    if (!content) {
80	        content = "";
81	    }
82	
83	    len = strlen(content);
84	    if (len >= response->output_size) {
85	        response->output[0] = '\0';
86	        return AGENT_ERROR_LIMIT;
87	    }
88	
89	    memcpy(response->output, content, len);
90	    response->output[len] = '\0';
91	    return AGENT_OK;
92	}
93	
94	static bool is_budget_error(int ret)
95	{
96	    return ret == AGENT_ERROR_LIMIT || ret == AGENT_ERROR_CONTEXT_OVERFLOW;
97	}
