99	static size_t align_up_size(size_t value)
100	{
101	    const size_t align = sizeof(void *);
102	
103	    return (value + align - 1u) & ~(align - 1u);
104	}
105	
106	static size_t estimate_request_arena_size(void)
107	{
108	    return (size_t)CAGENT_SYSTEM_CONTEXT_BUFFER_SIZE +
109	           (size_t)CAGENT_TOOL_SCHEMA_BUFFER_SIZE +
110	           (size_t)CAGENT_MESSAGES_BUFFER_SIZE;
111	}
112	
113	static int arena_begin(agent_t *agent, size_t required_size)
114	{
115	    size_t arena_size = (size_t)CAGENT_REQUEST_ARENA_SIZE;
116	
117	    if (!agent) {
118	        return AGENT_ERROR_INVALID;
119	    }
120	
121	    memset(&agent->request_arena, 0, sizeof(agent->request_arena));
122	    if (arena_size < required_size) {
123	        return AGENT_ERROR_LIMIT;
124	    }
125	
126	    agent->request_arena.buffer =
127	        (unsigned char *)agent_runtime_malloc(&agent->runtime, arena_size);
128	    if (!agent->request_arena.buffer) {
129	        return AGENT_ERROR_NOMEM;
130	    }
131	
132	    agent->request_arena.size = arena_size;
133	    return AGENT_OK;
134	}
135	
136	static void arena_end(agent_t *agent)
137	{
138	    if (!agent) {
139	        return;
140	    }
141	
142	    agent->stats.last_run_arena_peak_bytes = agent->request_arena.peak;
143	    if (agent->request_arena.peak > agent->stats.arena_peak_bytes) {
144	        agent->stats.arena_peak_bytes = agent->request_arena.peak;
145	    }
146	
147	    if (agent->request_arena.buffer) {
148	        agent_runtime_free(&agent->runtime, agent->request_arena.buffer);
149	    }
150	    memset(&agent->request_arena, 0, sizeof(agent->request_arena));
151	}
152	
153	static void *arena_alloc(agent_t *agent, size_t size)
154	{
155	    size_t aligned_used;
156	    size_t next_used;
157	    void *ptr;
158	
159	    if (!agent || !agent->request_arena.buffer || size == 0u) {
160	        return NULL;
161	    }
162	
163	    aligned_used = align_up_size(agent->request_arena.used);
164	    if (size > agent->request_arena.size - aligned_used) {
165	        return NULL;
166	    }
167	
168	    next_used = aligned_used + size;
169	    ptr = agent->request_arena.buffer + aligned_used;
170	    agent->request_arena.used = next_used;
171	    if (next_used > agent->request_arena.peak) {
172	        agent->request_arena.peak = next_used;
173	    }
174	
175	    memset(ptr, 0, size);
176	    return ptr;
177	}
178	
179	static int allocate_loop_buffers(agent_t *agent,
180	                                 char **context,
181	                                 char **tools,
182	                                 char **messages)
183	{
184	    if (!agent || !context || !tools || !messages) {
185	        return AGENT_ERROR_INVALID;
186	    }
187	
188	    *context = (char *)arena_alloc(agent, CAGENT_SYSTEM_CONTEXT_BUFFER_SIZE);
189	    *tools = (char *)arena_alloc(agent, CAGENT_TOOL_SCHEMA_BUFFER_SIZE);
190	    *messages = (char *)arena_alloc(agent, CAGENT_MESSAGES_BUFFER_SIZE);
191	    if (!*context || !*tools || !*messages) {
192	        *context = NULL;
193	        *tools = NULL;
194	        *messages = NULL;
195	        return AGENT_ERROR_LIMIT;
196	    }
197	
198	    return AGENT_OK;
199	}
200	
201	int agent_loop_run(agent_t *agent,
202	                   const agent_request_t *request,
203	                   agent_response_t *response)
204	{
205	    agent_session_t *session;
206	    agent_message_t user_message;
207	    char *context = NULL;
208	    char *tools_json = NULL;
209	    char *messages_json = NULL;
210	    uint32_t iter;
211	    int ret;
212	
213	    if (!agent || !request || !response) {
214	        return AGENT_ERROR_INVALID;
215	    }
216	
217	    if (!agent->model) {
218	        return AGENT_ERROR_INVALID;
219	    }
220	
221	    ret = check_run_state(agent);
222	    if (ret != AGENT_OK) {
223	        return ret;
224	    }
225	
226	    ret = arena_begin(agent, estimate_request_arena_size());
227	    if (ret != AGENT_OK) {
228	        return ret;
229	    }
230	
231	    ret = allocate_loop_buffers(agent, &context, &tools_json, &messages_json);
232	    if (ret != AGENT_OK) {
233	        arena_end(agent);
234	        return ret;
235	    }
236	
237	    session = agent_session_find_or_create(agent, request->session_id);
238	    if (!session) {
239	        arena_end(agent);
240	        return AGENT_ERROR_LIMIT;
241	    }
242	
243	    memset(&user_message, 0, sizeof(user_message));
244	    user_message.role = AGENT_MESSAGE_ROLE_USER;
245	    user_message.content = request->input;
246	    ret = agent_session_append(agent, request->session_id, &user_message);
247	    if (ret == AGENT_ERROR_INVALID) {
248	        int cleanup_ret = agent_session_drop_unfinished_tail(agent, session);
249	        if (cleanup_ret == AGENT_OK) {
250	            ret = agent_session_append(agent, request->session_id, &user_message);
251	        }
252	    }
253	    if (ret != AGENT_OK) {
254	        arena_end(agent);
255	        return ret;
256	    }
257	
258	    for (iter = 0u; iter < agent->limits.max_steps; iter++) {
259	        agent_model_request_t model_request;
260	        agent_model_response_t model_response;
261	        uint32_t budget_retry;
262	
263	        ret = check_run_state(agent);
264	        if (ret != AGENT_OK) {
265	            break;
266	        }
267	
268	        agent->stats.iterations++;
269	        agent_event_emit(agent,
270	                         AGENT_EVENT_ITERATION_START,
271	                         request,
272	                         iter + 1u,
273	                         AGENT_OK,
274	                         "step",
275	                         NULL,
276	                         NULL);
277	
278	        for (budget_retry = 0u;
279	             budget_retry <= CAGENT_MAX_SESSION_MESSAGES;
280	             budget_retry++) {
281	            ret = agent_context_build(agent,
282	                                      request,
283	                                      context,
284	                                      CAGENT_SYSTEM_CONTEXT_BUFFER_SIZE,
285	                                      NULL);
286	            if (ret != AGENT_OK) {
287	                break;
288	            }
289	
290	            ret = agent_tool_schema_build(agent,
291	                                          tools_json,
292	                                          CAGENT_TOOL_SCHEMA_BUFFER_SIZE,
293	                                          NULL);
294	            if (ret != AGENT_OK) {
295	                break;
296	            }
297	
298	            ret = agent_session_build_model_messages(agent,
299	                                                     session,
300	                                                     messages_json,
301	                                                     CAGENT_MESSAGES_BUFFER_SIZE,
302	                                                     NULL);
303	            if (is_budget_error(ret)) {
304	                int evict_ret = agent_session_evict_oldest_turn(agent, session);
305	                if (evict_ret == AGENT_OK) {
306	                    continue;
307	                }
308	            }
309	            if (ret != AGENT_OK) {
310	                break;
311	            }
312	
313	            memset(&model_request, 0, sizeof(model_request));
314	            model_request.context = context;
315	            model_request.tools_json = tools_json;
316	            model_request.messages_json = messages_json;
317	            model_request.session_id = request->session_id ? request->session_id
318	                                                           : AGENT_SESSION_DEFAULT_ID;
319	            model_request.input = request->input;
320	            model_request.trace_id = request->trace_id;
321	            model_request.timeout_ms = agent->limits.per_model_timeout_ms;
322	            model_request.max_output_tokens = agent->limits.max_output_tokens;
323	
324	            memset(&model_response, 0, sizeof(model_response));
325	            agent_event_emit(agent,
326	                             AGENT_EVENT_MODEL_REQUEST,
327	                             request,
328	                             iter + 1u,
329	                             AGENT_OK,
330	                             "request",
331	                             NULL,
332	                             NULL);
333	            ret = agent_model_complete(agent->model,
334	                                       &agent->runtime,
335	                                       &model_request,
336	                                       &model_response);
337	            agent->stats.model_calls++;
338	            agent_event_emit(agent,
339	                             AGENT_EVENT_MODEL_RESPONSE,
340	                             request,
341	                             iter + 1u,
342	                             ret,
343	                             error_code_to_str(ret),
344	                             NULL,
345	                             NULL);
346	            if (is_budget_error(ret)) {
347	                int evict_ret = agent_session_evict_oldest_turn(agent, session);
348	                if (evict_ret == AGENT_OK) {
349	                    continue;
350	                }
351	            }
352	            break;
353	        }
354	        if (ret != AGENT_OK) {
355	            break;
356	        }
357	        ret = check_run_state(agent);
358	        if (ret != AGENT_OK) {
359	            break;
360	        }
361	        if (model_response.status != AGENT_OK) {
362	            ret = model_response.status ? model_response.status : AGENT_ERROR_MODEL;
363	            break;
364	        }
365	
366	        if (model_response.tool_call_count > 0u) {
367	            size_t i;
368	
369	            if (!model_response.tool_calls) {
370	                ret = AGENT_ERROR_INVALID;
371	                break;
372	            }
373	
374	            ret = agent_session_add_assistant_tool_calls(agent,
375	                                                        session,
376	                                                        model_response.tool_calls,
377	                                                        model_response.tool_call_count);
378	            if (ret != AGENT_OK) {
379	                break;
380	            }
381	
382	            for (i = 0u; i < model_response.tool_call_count; i++) {
383	                agent_tool_result_t tool_result;
384	                const agent_tool_call_t *call = &model_response.tool_calls[i];
385	                int tool_status;
386	
387	                ret = check_run_state(agent);
388	                if (ret != AGENT_OK) {
389	                    break;
390	                }
391	
392	                agent_event_emit(agent,
393	                                 AGENT_EVENT_TOOL_CALL,
394	                                 request,
395	                                 iter + 1u,
396	                                 AGENT_OK,
397	                                 "call",
398	                                 call->name,
399	                                 call->id);
400	
401	                memset(&tool_result, 0, sizeof(tool_result));
402	                tool_status = agent_tool_execute(agent, call, &tool_result);
403	
404	                agent_event_emit(agent,
405	                                 AGENT_EVENT_TOOL_RESULT,
406	                                 request,
407	                                 iter + 1u,
408	                                 tool_status,
409	                                 tool_result.error_message,
410	                                 call->name,
411	                                 call->id);
412	
413	                ret = check_run_state(agent);
414	                if (ret != AGENT_OK) {
415	                    break;
416	                }
417	
418	                ret = agent_session_add_tool(agent,
419	                                             session,
420	                                             call->id,
421	                                             tool_result.content_json);
422	                if (ret != AGENT_OK) {
423	                    break;
424	                }
425	            }
426	
427	            if (ret != AGENT_OK) {
428	                break;
429	            }
430	            continue;
431	        }
432	
433	        ret = agent_session_add_assistant(agent, session, model_response.content);
434	        if (ret != AGENT_OK) {
435	            break;
436	        }
437	
438	        ret = copy_final_output(response, model_response.content);
439	        break;
440	    }
441	
442	    if (iter >= agent->limits.max_steps && ret == AGENT_OK) {
443	        ret = AGENT_ERROR_LIMIT;
444	    } else if (iter >= agent->limits.max_steps && ret == 0) {
445	        ret = AGENT_ERROR_LIMIT;
446	    }
447	
448	    if (ret == AGENT_OK) {
449	        arena_end(agent);
450	        return AGENT_OK;
451	    }
452	
453	    agent_session_drop_unfinished_tail(agent, session);
454	    arena_end(agent);
455	    return ret ? ret : AGENT_ERROR_LIMIT;
456	}
