1	/* SPDX-License-Identifier: Apache-2.0 */
2	/**
3	 * Session 管理器 — bounded in-memory 对话历史。
4	 *
5	 * 必须保持 tool calling 消息链完整：
6	 *   user → assistant(tool_calls) → tool(call_id) → assistant(final)
7	 *
8	 * 淘汰策略（按完整 turn）：
9	 *   - turn 边界：user message → assistant(final) message
10	 *   - 只淘汰完整 turn，不留下孤立 assistant(tool_calls)
11	 *   - 尾部未完成 turn 不参与淘汰
12	 *   - 无完整 turn 可淘汰时返回 AGENT_ERROR_LIMIT
13	 *
14	 * 消息内容内拷贝到固定缓冲区，不持有外部指针。
15	 */
16	
17	#include "memory_internal.h"
18	
19	#include "../core/agent_internal.h"
20	#include "../runtime/runtime.h"
21	#include "../types_internal.h"
22	
23	#include <stdbool.h>
24	#include <stdio.h>
25	#include <string.h>
26	
27	/* ── 内部辅助函数 ── */
28	
29	/**
30	 * 拷贝字符串到固定缓冲区。
31	 * 缓冲区不足时返回 AGENT_ERROR_LIMIT，不静默截断。
32	 */
33	static int copy_string(char *dst,
34	                       size_t dst_size,
35	                       const char *src,
36	                       bool allow_null,
37	                       size_t *written)
38	{
39	    size_t len;
40	
41	    if (!dst || dst_size == 0u) {
42	        return AGENT_ERROR_INVALID;
43	    }
44	
45	    if (!src) {
46	        if (!allow_null) {
47	            return AGENT_ERROR_INVALID;
48	        }
49	        dst[0] = '\0';
50	        if (written) {
51	            *written = 0u;
52	        }
53	        return AGENT_OK;
54	    }
55	
56	    len = strlen(src);
57	    if (len >= dst_size) {
58	        dst[0] = '\0';
59	        return AGENT_ERROR_LIMIT;
60	    }
61	
62	    memcpy(dst, src, len);
63	    dst[len] = '\0';
64	    if (written) {
65	        *written = len;
66	    }
67	    return AGENT_OK;
68	}
69	
70	static const char *normalize_session_id(const char *session_id)
71	{
72	    return session_id ? session_id : AGENT_SESSION_DEFAULT_ID;
73	}
74	
75	static bool session_id_valid(const char *session_id)
76	{
77	    const char *id = normalize_session_id(session_id);
78	
79	    return strlen(id) < sizeof(((agent_session_t *)0)->id);
80	}
81	
82	/**
83	 * 检查 entry 是否为 assistant final 消息。
84	 *
85	 * assistant final = role 为 ASSISTANT 且无 tool_calls。
86	 * 这种消息标记一个 turn 的结束。
87	 */
88	static bool entry_is_assistant_final(const agent_session_entry_t *entry)
89	{
90	    return entry && entry->role == AGENT_MESSAGE_ROLE_ASSISTANT
91	           && entry->tool_call_count == 0u;
92	}
93	
94	static bool session_has_unfinished_turn(const agent_session_t *session)
95	{
96	    uint32_t i;
97	
98	    if (!session || session->count == 0u) {
99	        return false;
100	    }
101	
102	    for (i = session->count; i > 0u; i--) {
103	        const agent_session_entry_t *entry = &session->entries[i - 1u];
104	        if (entry_is_assistant_final(entry)) {
105	            return false;
106	        }
107	        if (entry->turn_boundary) {
108	            return true;
109	        }
110	    }
111	
112	    return false;
113	}
114	
115	static bool tool_call_answered_after(const agent_session_t *session,
116	                                     uint32_t assistant_index,
117	                                     const char *tool_call_id)
118	{
119	    uint32_t i;
120	
121	    for (i = assistant_index + 1u; i < session->count; i++) {
122	        const agent_session_entry_t *entry = &session->entries[i];
123	        if (entry->turn_boundary) {
124	            break;
125	        }
126	        if (entry->role == AGENT_MESSAGE_ROLE_TOOL
127	            && strcmp(entry->tool_call_id, tool_call_id) == 0) {
128	            return true;
129	        }
130	    }
131	
132	    return false;
133	}
134	
135	static bool session_has_pending_tool_calls(const agent_session_t *session)
136	{
137	    uint32_t turn_start;
138	    uint32_t i;
139	
140	    if (!session || session->count == 0u) {
141	        return false;
142	    }
143	
144	    turn_start = UINT32_MAX;
145	    for (i = session->count; i > 0u; i--) {
146	        if (session->entries[i - 1u].turn_boundary) {
147	            turn_start = i - 1u;
148	            break;
149	        }
150	        if (entry_is_assistant_final(&session->entries[i - 1u])) {
151	            return false;
152	        }
153	    }
154	
155	    if (turn_start == UINT32_MAX) {
156	        return false;
157	    }
158	
159	    for (i = turn_start; i < session->count; i++) {
160	        const agent_session_entry_t *entry = &session->entries[i];
161	        uint32_t call_index;
162	
163	        if (entry->role != AGENT_MESSAGE_ROLE_ASSISTANT
164	            || entry->tool_call_count == 0u) {
165	            continue;
166	        }
167	
168	        for (call_index = 0u; call_index < entry->tool_call_count; call_index++) {
169	            if (!tool_call_answered_after(session,
170	                                          i,
171	                                          entry->tool_calls[call_index].id)) {
172	                return true;
173	            }
174	        }
175	    }
176	
177	    return false;
178	}
179	
180	static bool session_has_pending_tool_call(const agent_session_t *session,
181	                                          const char *tool_call_id)
182	{
183	    uint32_t i;
184	
185	    if (!session || !tool_call_id) {
186	        return false;
187	    }
188	
189	    for (i = session->count; i > 0u; i--) {
190	        const agent_session_entry_t *entry = &session->entries[i - 1u];
191	        uint32_t call_index;
192	
193	        if (entry->turn_boundary || entry_is_assistant_final(entry)) {
194	            break;
195	        }
196	
197	        if (entry->role == AGENT_MESSAGE_ROLE_TOOL
198	            && strcmp(entry->tool_call_id, tool_call_id) == 0) {
199	            return false;
200	        }
201	
202	        if (entry->role != AGENT_MESSAGE_ROLE_ASSISTANT
203	            || entry->tool_call_count == 0u) {
204	            continue;
205	        }
206	
207	        for (call_index = 0u; call_index < entry->tool_call_count; call_index++) {
208	            if (strcmp(entry->tool_calls[call_index].id, tool_call_id) == 0) {
209	                return true;
210	            }
211	        }
212	    }
213	
214	    return false;
215	}
216	
217	static int append_raw(char *buffer, size_t buffer_size, size_t *used, const char *text)
218	{
219	    size_t len;
220	
221	    if (!buffer || !used || !text) {
222	        return AGENT_ERROR_INVALID;
223	    }
224	
225	    len = strlen(text);
226	    if (*used + len >= buffer_size) {
227	        return AGENT_ERROR_LIMIT;
228	    }
229	
230	    memcpy(buffer + *used, text, len);
231	    *used += len;
232	    buffer[*used] = '\0';
233	    return AGENT_OK;
234	}
235	
236	static int append_char(char *buffer, size_t buffer_size, size_t *used, char c)
237	{
238	    if (!buffer || !used) {
239	        return AGENT_ERROR_INVALID;
240	    }
241	
242	    if (*used + 1u >= buffer_size) {
243	        return AGENT_ERROR_LIMIT;
244	    }
245	
246	    buffer[(*used)++] = c;
247	    buffer[*used] = '\0';
248	    return AGENT_OK;
249	}
250	
251	static int append_json_string(char *buffer,
252	                              size_t buffer_size,
253	                              size_t *used,
254	                              const char *text)
255	{
256	    int err;
257	
258	    err = append_char(buffer, buffer_size, used, '"');
259	    if (err != AGENT_OK) {
260	        return err;
261	    }
262	
263	    if (text) {
264	        while (*text) {
265	            unsigned char c = (unsigned char)*text++;
266	            char escaped[7];
267	            const char *replacement = NULL;
268	
269	            switch (c) {
270	            case '\\':
271	                replacement = "\\\\";
272	                break;
273	            case '"':
274	                replacement = "\\\"";
275	                break;
276	            case '\b':
277	                replacement = "\\b";
278	                break;
279	            case '\f':
280	                replacement = "\\f";
281	                break;
282	            case '\n':
283	                replacement = "\\n";
284	                break;
285	            case '\r':
286	                replacement = "\\r";
287	                break;
288	            case '\t':
289	                replacement = "\\t";
290	                break;
291	            default:
292	                if (c < 0x20u) {
293	                    snprintf(escaped, sizeof(escaped), "\\u%04x", c);
294	                    replacement = escaped;
295	                }
296	                break;
297	            }
298	
299	            if (replacement) {
300	                err = append_raw(buffer, buffer_size, used, replacement);
301	            } else {
302	                err = append_char(buffer, buffer_size, used, (char)c);
303	            }
304	            if (err != AGENT_OK) {
305	                return err;
306	            }
307	        }
308	    }
309	
310	    return append_char(buffer, buffer_size, used, '"');
311	}
