313	static const char *message_role_name(agent_message_role_t role)
314	{
315	    switch (role) {
316	    case AGENT_MESSAGE_ROLE_USER:
317	        return "user";
318	    case AGENT_MESSAGE_ROLE_ASSISTANT:
319	        return "assistant";
320	    case AGENT_MESSAGE_ROLE_TOOL:
321	        return "tool";
322	    default:
323	        return NULL;
324	    }
