403	        if (err != AGENT_OK) {
404	            return err;
405	        }
406	        err = append_raw(buffer,
407	                         buffer_size,
408	                         used,
409	                         ",\"type\":\"function\",\"function\":{\"name\":");
410	        if (err != AGENT_OK) {
411	            return err;
412	        }
413	        err = append_json_string(buffer, buffer_size, used, call->name);
414	        if (err != AGENT_OK) {
415	            return err;
416	        }
417	        err = append_raw(buffer, buffer_size, used, ",\"arguments\":");
418	        if (err != AGENT_OK) {
419	            return err;
420	        }
421	        err = append_json_string(buffer, buffer_size, used, call->arguments_json);
422	        if (err != AGENT_OK) {
423	            return err;
424	        }
425	        err = append_raw(buffer, buffer_size, used, "}}");
426	        if (err != AGENT_OK) {
