436	/** 按 id 查找 session，不存在返回 NULL */
437	agent_session_t *agent_session_find(agent_t *agent, const char *session_id)
438	{
439	    uint32_t i;
440	
441	    session_id = normalize_session_id(session_id);
442	
443	    if (!agent || !session_id || !session_id_valid(session_id)) {
444	        return NULL;
445	    }
446	
447	    for (i = 0u; i < agent->session_count; i++) {
448	        if (strcmp(agent->sessions[i].id, session_id) == 0) {
449	            return &agent->sessions[i];
