457	 * 查找或创建 session。
458	 *
459	 * 不存在时自动创建并初始化。
460	 * session 数组已满时返回 NULL。
461	 */
462	agent_session_t *agent_session_find_or_create(agent_t *agent, const char *session_id)
463	{
464	    agent_session_t *session;
465	
466	    session_id = normalize_session_id(session_id);
467	
468	    if (!agent || !session_id || !session_id_valid(session_id)) {
469	        return NULL;
470	    }
471	
472	    /* 先查找已有 session */
473	    session = agent_session_find(agent, session_id);
474	    if (session) {
475	        return session;
476	    }
477	
478	    /* 创建新 session */
479	    if (agent->session_count >= CAGENT_MAX_SESSIONS) {
480	        return NULL;
481	    }
482	
483	    session = &agent->sessions[agent->session_count];
484	    memset(session, 0, sizeof(*session));
485	    if (copy_string(session->id, sizeof(session->id), session_id, false, NULL) != AGENT_OK) {
486	        return NULL;
487	    }
488	    agent->session_count++;
489	
490	    return session;
491	}
