501	static int ensure_space(agent_t *agent, agent_session_t *session)
502	{
503	    int err;
504	
505	    if (session->count < CAGENT_MAX_SESSION_MESSAGES) {
506	        return AGENT_OK;
507	    }
508	
509	    /* 满了，尝试淘汰 */
510	    err = agent_session_evict_oldest_turn(agent, session);
511	    if (err != AGENT_OK) {
512	        return err;
513	    }
514	
515	    /* 淘汰后仍满（理论上不应发生，但防御性检查） */
516	    if (session->count >= CAGENT_MAX_SESSION_MESSAGES) {
517	        return AGENT_ERROR_LIMIT;
518	    }
519	
520	    return AGENT_OK;
