740	/* ── Turn 淘汰 ── */
741	
742	/**
743	 * 淘汰最早的完整 turn。
744	 *
745	 * 淘汰规则：
746	 *   1. 从头部扫描，找到第一个 turn_boundary（user message）
747	 *   2. 从该位置继续扫描，找到对应的 assistant final 消息
748	 *   3. 如果找到，删除从 user 到 assistant(final) 的所有消息
749	 *   4. 尾部未完成 turn（user 后无 assistant final）不参与淘汰
750	 *   5. 无完整 turn 时返回 AGENT_ERROR_LIMIT
751	 *
752	 * 删除通过 memmove 实现，保持消息顺序。
753	 */
754	int agent_session_evict_oldest_turn(agent_t *agent, agent_session_t *session)
755	{
756	    uint32_t turn_start;
757	    uint32_t turn_end;
758	    uint32_t i;
759	    bool found_final;
760	
761	    CAGENT_UNUSED(agent);
762	
763	    if (!session || session->count == 0u) {
764	        return AGENT_ERROR_LIMIT;
765	    }
766	
767	    /* 从头部找到第一个完整 turn 的边界 */
768	    turn_start = UINT32_MAX;
769	    turn_end = 0u;
770	    found_final = false;
771	
772	    for (i = 0u; i < session->count; i++) {
773	        if (session->entries[i].turn_boundary) {
774	            /* 找到 turn 起点 */
775	            turn_start = i;
776	            /* 继续找这个 turn 的终点（assistant final） */
777	            turn_end = i + 1u;
778	            while (turn_end < session->count) {
779	                if (session->entries[turn_end].turn_boundary) {
780	                    break;
781	                }
782	                if (entry_is_assistant_final(&session->entries[turn_end])) {
783	                    found_final = true;
784	                    break;
785	                }
786	                turn_end++;
787	            }
788	            break;
789	        }
790	    }
791	
792	    /* 没有找到 turn 起点，或 turn 未完成 */
793	    if (turn_start == UINT32_MAX || !found_final) {
794	        return AGENT_ERROR_LIMIT;
795	    }
796	
797	    /* turn_end 指向 assistant final，要删除 [turn_start, turn_end] 范围 */
798	    /* 删除条数 = turn_end - turn_start + 1 */
799	    uint32_t remove_count = turn_end - turn_start + 1u;
800	    uint32_t remaining = session->count - turn_start - remove_count;
801	
802	    if (remaining > 0u) {
803	        memmove(&session->entries[turn_start],
804	                &session->entries[turn_end + 1u],
805	                remaining * sizeof(agent_session_entry_t));
806	    }
807	
808	    session->count -= remove_count;
809	
810	    /* 清零尾部残留 */
811	    memset(&session->entries[session->count], 0,
812	           remove_count * sizeof(agent_session_entry_t));
813	
814	    if (session->complete_turns > 0u) {
815	        session->complete_turns--;
816	    }
817	
818	    return AGENT_OK;
819	}
820	
821	/**
822	 * 删除尾部未完成 turn。
823	 *
824	 * 用于 agent_run 失败恢复：如果本轮已经追加 user / tool_calls / tool result，
825	 * 但还没有形成 assistant final，则删除从最后一个 user turn_boundary 到尾部的
826	 * 所有消息。已经完成的历史 turn 保留，已经发生的完整 turn 淘汰也不回滚。
827	 */
828	int agent_session_drop_unfinished_tail(agent_t *agent, agent_session_t *session)
829	{
830	    uint32_t turn_start;
831	    uint32_t remove_count;
832	    uint32_t i;
833	
834	    CAGENT_UNUSED(agent);
835	
836	    if (!session) {
837	        return AGENT_ERROR_INVALID;
838	    }
839	
840	    if (session->count == 0u) {
841	        return AGENT_OK;
842	    }
843	
844	    turn_start = UINT32_MAX;
845	    for (i = session->count; i > 0u; i--) {
846	        agent_session_entry_t *entry = &session->entries[i - 1u];
847	
848	        if (entry_is_assistant_final(entry)) {
849	            return AGENT_OK;
850	        }
851	
852	        if (entry->turn_boundary) {
853	            turn_start = i - 1u;
854	            break;
855	        }
856	    }
857	
858	    if (turn_start == UINT32_MAX) {
859	        return AGENT_OK;
860	    }
861	
862	    remove_count = session->count - turn_start;
863	    memset(&session->entries[turn_start],
864	           0,
865	           remove_count * sizeof(agent_session_entry_t));
866	    session->count = turn_start;
867	    return AGENT_OK;
868	}
