938	 * 根据 message->role 分发到对应的内部 add 函数。
939	 * 对于 ASSISTANT 角色，无法通过此接口传递 tool_calls，
940	 * 应用层应通过 agent_run 间接使用 session。
941	 */
942	int agent_session_append(agent_t *agent,
943	                         const char *session_id,
944	                         const agent_message_t *message)
945	{
946	    agent_session_t *session;
947	
948	    if (!agent || !message) {
949	        return AGENT_ERROR_INVALID;
950	    }
951	
952	    session = agent_session_find_or_create(agent, session_id);
953	    if (!session) {
954	        return AGENT_ERROR_LIMIT;
955	    }
956	
957	    switch (message->role) {
958	    case AGENT_MESSAGE_ROLE_USER:
959	        return agent_session_add_user(agent, session, message->content);
960	
961	    case AGENT_MESSAGE_ROLE_ASSISTANT:
962	        return agent_session_add_assistant(agent, session, message->content);
963	
964	    case AGENT_MESSAGE_ROLE_TOOL:
965	        return agent_session_add_tool(agent, session,
966	                                      message->tool_call_id, message->content);
967	
968	    case AGENT_MESSAGE_ROLE_SYSTEM:
969	        /* system 消息由 context_builder 管理，不直接追加到 session */
970	        return AGENT_ERROR_INVALID;
971	
972	    default:
973	        return AGENT_ERROR_INVALID;
974	    }
975	}
