977	int agent_session_build_model_messages(agent_t *agent,
978	                                       agent_session_t *session,
979	                                       char *buffer,
980	                                       size_t buffer_size,
981	                                       size_t *written)
982	{
983	    uint32_t i;
984	    size_t used = 0u;
985	    int err;
986	
987	    CAGENT_UNUSED(agent);
988	
989	    if (!session || !buffer || buffer_size == 0u) {
990	        return AGENT_ERROR_INVALID;
991	    }
992	
993	    buffer[0] = '\0';
994	
995	    err = append_char(buffer, buffer_size, &used, '[');
996	    if (err != AGENT_OK) {
997	        return err;
998	    }
999	
1000	    for (i = 0u; i < session->count; i++) {
1001	        const agent_session_entry_t *entry = &session->entries[i];
1002	
1003	        if (entry->role == AGENT_MESSAGE_ROLE_SYSTEM) {
1004	            continue;
1005	        }
1006	
1007	        if (used > 1u) {
1008	            err = append_char(buffer, buffer_size, &used, ',');
1009	            if (err != AGENT_OK) {
1010	                return err;
1011	            }
1012	        }
1013	
1014	        if (entry->role == AGENT_MESSAGE_ROLE_ASSISTANT
1015	            && entry->tool_call_count > 0u) {
1016	            err = append_assistant_tool_calls_message(buffer,
1017	                                                      buffer_size,
1018	                                                      &used,
1019	                                                      entry);
1020	        } else {
1021	            err = append_content_message(buffer, buffer_size, &used, entry);
1022	        }
1023	        if (err != AGENT_OK) {
1024	            return err;
1025	        }
1026	    }
1027	
1028	    err = append_char(buffer, buffer_size, &used, ']');
1029	    if (err != AGENT_OK) {
1030	        return err;
1031	    }
1032	
1033	    if (written) {
1034	        *written = used;
1035	    }
1036	
1037	    return AGENT_OK;
1038	}
