82	static const char *find_json_value(const char *json, const char *key)
83	{
84	    const char *p;
85	
86	    if (!json || !key) {
87	        return NULL;
88	    }
89	
90	    p = strstr(json, key);
91	    if (!p) {
92	        return NULL;
93	    }
94	
95	    p = strchr(p + strlen(key), ':');
96	    if (!p) {
97	        return NULL;
98	    }
99	
100	    p++;
101	    while (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n') {
102	        p++;
103	    }
104	
105	    return p;
106	}
107	
108	static int json_get_int(const char *json, const char *key, int *out)
109	{
110	    const char *p = find_json_value(json, key);
111	    char *end = NULL;
112	    long value;
113	
114	    if (!p || !out) {
115	        return AGENT_ERROR_INVALID;
116	    }
117	
118	    value = strtol(p, &end, 10);
119	    if (end == p) {
120	        return AGENT_ERROR_INVALID;
121	    }
122	
123	    *out = (int)value;
124	    return AGENT_OK;
125	}
126	
127	static int json_get_bool(const char *json, const char *key, int *out)
128	{
129	    const char *p = find_json_value(json, key);
130	
131	    if (!p || !out) {
132	        return AGENT_ERROR_INVALID;
133	    }
134	
135	    if (strncmp(p, "true", 4) == 0) {
136	        *out = 1;
137	        return AGENT_OK;
138	    }
139	
140	    if (strncmp(p, "false", 5) == 0) {
141	        *out = 0;
142	        return AGENT_OK;
143	    }
144	
145	    return AGENT_ERROR_INVALID;
146	}
147	
148	static int json_get_string(const char *json,
149	                           const char *key,
150	                           char *out,
151	                           size_t out_size)
152	{
153	    const char *p = find_json_value(json, key);
154	    size_t used = 0u;
155	
156	    if (!p || !out || out_size == 0u || *p != '"') {
157	        return AGENT_ERROR_INVALID;
158	    }
159	
160	    p++;
161	    while (*p && *p != '"' && used + 1u < out_size) {
162	        if (*p == '\\' && p[1]) {
163	            p++;
164	            if (*p == 'n') {
165	                out[used++] = '\n';
166	            } else if (*p == 'r') {
167	                out[used++] = '\r';
168	            } else if (*p == 't') {
169	                out[used++] = '\t';
170	            } else {
171	                out[used++] = *p;
172	            }
173	            p++;
174	            continue;
175	        }
176	        out[used++] = *p++;
177	    }
178	    out[used] = '\0';
179	
180	    return *p == '"' ? AGENT_OK : AGENT_ERROR_LIMIT;
181	}
