473	int smart_home_device_run_scene(smart_home_state_t *state,
474	                                const char *scene)
475	{
476	    if (!state || !scene) {
477	        return AGENT_ERROR_INVALID;
478	    }
479	
480	    if (strcmp(scene, "sleep") == 0) {
481	        smart_home_device_set_light(state, "living_room", 0, 0);
482	        smart_home_device_set_light(state, "bedroom", 1, 10);
483	        smart_home_device_set_ac(state, "bedroom", 1, 0, 3, 26);
484	        return AGENT_OK;
485	    }
486	
487	    if (strcmp(scene, "movie") == 0) {
488	        smart_home_device_set_light(state, "living_room", 1, 20);
489	        smart_home_device_set_light(state, "bedroom", 0, 0);
490	        smart_home_device_set_ac(state, "bedroom", 1, 0, 0, 24);
491	        return AGENT_OK;
492	    }
493	
494	    if (strcmp(scene, "away") == 0) {
495	        int i;
496	
497	        for (i = 0; i < SMART_HOME_MAX_DEVICES; i++) {
498	            smart_home_device_t *device = &state->devices[i];
499	
500	            if (!device->used) {
501	                continue;
502	            }
503	            device->on = 0;
504	            if (device->type == SMART_HOME_DEVICE_LIGHT) {
505	                device->brightness = 0;
506	            }
507	        }
508	        return AGENT_OK;
509	    }
510	
511	    if (strcmp(scene, "home") == 0) {
512	        smart_home_device_set_light(state, "living_room", 1, 65);
513	        smart_home_device_set_light(state, "bedroom", 1, 35);
514	        smart_home_device_set_ac(state, "bedroom", 1, 4, 3, 25);
515	        return AGENT_OK;
516	    }
517	
518	    return AGENT_ERROR_NOTFOUND;
519	}
