17	#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
18	#include "tensorflow/lite/schema/schema_generated.h"
19	
20	namespace
21	{
22	
23	alignas(16) uint8_t g_tensor_arena[CONFIG_EXAMPLES_AUDIO_EVENT_ARENA_SIZE];
24	
25	tflite::MicroInterpreter *g_interpreter;
26	TfLiteTensor *g_input;
27	TfLiteTensor *g_output;
28	size_t g_arena_used;
29	
30	bool tensor_shape_is(const TfLiteTensor *tensor, int first, int second)
31	{
32	  return tensor != nullptr && tensor->dims != nullptr &&
33	         tensor->dims->size == 2 && tensor->dims->data[0] == first &&
34	         tensor->dims->data[1] == second;
35	}
36	
37	int read_output(float *probabilities, size_t class_count)
38	{
39	  if (g_output == nullptr || probabilities == nullptr ||
40	      class_count != AUDIO_EVENT_CLASS_COUNT)
41	    {
42	      return -EINVAL;
43	    }
44	
45	  for (size_t i = 0; i < class_count; i++)
46	    {
47	      probabilities[i] =
48	          (static_cast<int>(g_output->data.int8[i]) -
49	           g_output->params.zero_point) *
50	          g_output->params.scale;
51	    }
52	
53	  return 0;
54	}
55	
56	}  // namespace
57	
58	extern "C" int event_classifier_init(void)
59	{
60	  static tflite::MicroMutableOpResolver<9> resolver;
61	  static bool resolver_initialized;
62	
63	  const tflite::Model *model = tflite::GetModel(g_audio_event_model);
64	  if (model == nullptr || model->version() != TFLITE_SCHEMA_VERSION)
65	    {
66	      std::fprintf(stderr, "[model] schema mismatch: model=%d runtime=%d\n",
67	                   model == nullptr ? -1 : model->version(),
68	                   TFLITE_SCHEMA_VERSION);
69	      return -EINVAL;
70	    }
71	
72	  if (!resolver_initialized)
73	    {
74	      if (resolver.AddShape() != kTfLiteOk ||
75	          resolver.AddStridedSlice() != kTfLiteOk ||
76	          resolver.AddPack() != kTfLiteOk ||
77	          resolver.AddReshape() != kTfLiteOk ||
78	          resolver.AddConv2D() != kTfLiteOk ||
79	          resolver.AddDepthwiseConv2D() != kTfLiteOk ||
80	          resolver.AddMean() != kTfLiteOk ||
81	          resolver.AddFullyConnected() != kTfLiteOk ||
82	          resolver.AddSoftmax() != kTfLiteOk)
83	        {
84	          std::fprintf(stderr, "[model] failed to register operators\n");
85	          return -EINVAL;
86	        }
87	
88	      resolver_initialized = true;
89	    }
90	
91	  static tflite::MicroInterpreter interpreter(
92	      model, resolver, g_tensor_arena, sizeof(g_tensor_arena));
93	
94	  if (interpreter.AllocateTensors() != kTfLiteOk)
95	    {
96	      std::fprintf(stderr, "[model] AllocateTensors failed, arena=%zu\n",
97	                   sizeof(g_tensor_arena));
98	      return -ENOMEM;
99	    }
100	
101	  g_interpreter = &interpreter;
102	  g_input = interpreter.input(0);
103	  g_output = interpreter.output(0);
104	  g_arena_used = interpreter.arena_used_bytes();
105	
106	  if (g_input == nullptr || g_input->type != kTfLiteInt8 ||
107	      !tensor_shape_is(g_input, 1, AUDIO_EVENT_FEATURE_SIZE))
108	    {
109	      std::fprintf(stderr, "[model] expected int8 input [1,%d]\n",
110	                   AUDIO_EVENT_FEATURE_SIZE);
111	      event_classifier_deinit();
112	      return -EINVAL;
113	    }
114	
115	  if (g_output == nullptr || g_output->type != kTfLiteInt8 ||
116	      !tensor_shape_is(g_output, 1, AUDIO_EVENT_CLASS_COUNT))
117	    {
118	      std::fprintf(stderr, "[model] expected int8 output [1,%d]\n",
119	                   AUDIO_EVENT_CLASS_COUNT);
120	      event_classifier_deinit();
121	      return -EINVAL;
122	    }
123	
124	  std::printf("[model] input=int8[1,%d] scale=%.9g zp=%ld\n",
125	              AUDIO_EVENT_FEATURE_SIZE,
126	              static_cast<double>(g_input->params.scale),
127	              static_cast<long>(g_input->params.zero_point));
128	  std::printf("[model] output=int8[1,%d] scale=%.9g zp=%ld\n",
129	              AUDIO_EVENT_CLASS_COUNT,
130	              static_cast<double>(g_output->params.scale),
131	              static_cast<long>(g_output->params.zero_point));
132	  std::printf("[model] arena=%zu used=%zu model=%u bytes\n",
133	              sizeof(g_tensor_arena), g_arena_used,
134	              g_audio_event_model_len);
135	  return 0;
136	}
137	
138	extern "C" void event_classifier_deinit(void)
139	{
140	  g_interpreter = nullptr;
141	  g_input = nullptr;
142	  g_output = nullptr;
143	  g_arena_used = 0;
144	}
145	
146	extern "C" int event_classifier_predict_quantized(
147	    const int8_t *features, size_t feature_count, float *probabilities,
148	    size_t class_count)
149	{
150	  if (g_interpreter == nullptr || g_input == nullptr || features == nullptr ||
151	      feature_count != AUDIO_EVENT_FEATURE_SIZE ||
152	      class_count != AUDIO_EVENT_CLASS_COUNT)
153	    {
154	      return -EINVAL;
155	    }
156	
157	  std::memcpy(g_input->data.int8, features, feature_count);
158	  if (g_interpreter->Invoke() != kTfLiteOk)
159	    {
160	      std::fprintf(stderr, "[model] Invoke failed\n");
161	      return -EIO;
162	    }
163	
164	  return read_output(probabilities, class_count);
165	}
166	
167	extern "C" int event_classifier_predict(const float *features,
168	                                        size_t feature_count,
169	                                        float *probabilities,
170	                                        size_t class_count)
171	{
172	  if (g_interpreter == nullptr || g_input == nullptr || features == nullptr ||
173	      feature_count != AUDIO_EVENT_FEATURE_SIZE ||
174	      class_count != AUDIO_EVENT_CLASS_COUNT ||
175	      g_input->params.scale <= 0.0f)
176	    {
177	      return -EINVAL;
178	    }
179	
180	  for (size_t i = 0; i < feature_count; i++)
181	    {
182	      long value = std::lround(features[i] / g_input->params.scale) +
183	                   g_input->params.zero_point;
184	      if (value < -128)
185	        {
186	          value = -128;
187	        }
188	      else if (value > 127)
189	        {
190	          value = 127;
191	        }
192	
193	      g_input->data.int8[i] = static_cast<int8_t>(value);
194	    }
195	
196	  if (g_interpreter->Invoke() != kTfLiteOk)
197	    {
198	      std::fprintf(stderr, "[model] Invoke failed\n");
199	      return -EIO;
200	    }
201	
202	  return read_output(probabilities, class_count);
203	}
204	
205	extern "C" size_t event_classifier_arena_used(void)
206	{
207	  return g_arena_used;
208	}
